from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    begin = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    result = []

    def append_if_valid(candidate):
        if candidate >= begin:
            result.append(candidate.isoformat())

    if kind == "DAILY":
        current = begin
        while len(result) < count:
            result.append(current.isoformat())
            current += timedelta(days=interval)
        return result

    if kind == "WEEKLY":
        weekdays = {
            "MO": 0, "TU": 1, "WE": 2, "TH": 3,
            "FR": 4, "SA": 5, "SU": 6,
        }
        selected = sorted(weekdays[day] for day in parts[2].split(","))
        week_start = begin - timedelta(days=begin.weekday())
        week_index = 0
        while len(result) < count:
            base = week_start + timedelta(weeks=week_index * interval)
            for weekday in selected:
                candidate = base + timedelta(days=weekday)
                append_if_valid(candidate)
                if len(result) == count:
                    break
            week_index += 1
        return result

    if kind == "MONTHLY":
        month_index = 0
        while len(result) < count:
            absolute_month = begin.year * 12 + begin.month - 1 + month_index * interval
            year, month0 = divmod(absolute_month, 12)
            month = month0 + 1
            last_day = calendar.monthrange(year, month)[1]

            if len(parts) == 3:
                day = int(parts[2])
                day = last_day if day == -1 else day
                if day <= last_day:
                    append_if_valid(date(year, month, day))
            else:
                n = int(parts[2])
                weekday = {
                    "MO": 0, "TU": 1, "WE": 2, "TH": 3,
                    "FR": 4, "SA": 5, "SU": 6,
                }[parts[3]]
                if n == -1:
                    day = last_day - ((date(year, month, last_day).weekday() - weekday) % 7)
                    append_if_valid(date(year, month, day))
                else:
                    first_weekday = date(year, month, 1).weekday()
                    day = 1 + ((weekday - first_weekday) % 7) + 7 * (n - 1)
                    if day <= last_day:
                        append_if_valid(date(year, month, day))

            month_index += 1
        return result

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year_index = 0
        while len(result) < count:
            year = begin.year + year_index * interval
            try:
                candidate = date(year, month, day)
            except ValueError:
                candidate = None
            if candidate is not None:
                append_if_valid(candidate)
            year_index += 1
        return result

    return result
